    pub(crate) fn finish_tail_cold<C: Copy, const N: usize>(
        remainder: &mut [f32],
        ctx: C,
        convert: fn(C, [f32; N]) -> [f32; N],
    ) {
        let mut block = [0.0; N];
        block[..remainder.len()].copy_from_slice(remainder);
        let converted = convert(ctx, block);
        remainder.copy_from_slice(&converted[..remainder.len()]);
    }
